{
  "title": "从基础录入到自动化服务",
  "baseline": "基于22岁的便利店店员身份，高中/中专学历，基础录入技能，无编程经验，只有个人电脑，不辞职，不购买课程，不编造收入与客户，90天内完成一个Excel表格自动化服务的付费试单。",
  "chapters": [
    {
      "name": "学习Excel基础",
      "period": "第1-2周",
      "narrative": "虚构测试甲开始学习Excel的基础知识，利用网络资源自学。",
      "gate": "能够熟练使用Excel进行基本的数据录入和简单的公式计算。",
      "quests": [
        {
          "title": "学习Excel基本功能",
          "steps": [
            "第一步：观看在线教程，学习Excel的基本界面和常用功能。",
            "第二步：练习使用Excel录入数据，创建一个包含姓名、年龄、性别、联系方式的表格。",
            "第三步：使用SUM、AVERAGE等基本函数进行数据计算，练习计算表格中年龄的平均值。"
          ],
          "output": "一个包含姓名、年龄、性别、联系方式的表格，以及计算出的年龄平均值。",
          "tool": "个人电脑，网络教程",
          "example": "姓名：张三，年龄：22，性别：男，联系方式：12345678901",
          "minutes": 45,
          "why": "通过自学Excel基础，为后续的自动化服务打下基础。"
        }
      ]
    },
    {
      "name": "探索自动化功能",
      "period": "第3-4周",
      "narrative": "虚构测试甲开始探索Excel的自动化功能，如宏和VBA。",
      "gate": "能够编写简单的宏和VBA代码，实现自动化数据处理。",
      "quests": [
        {
          "title": "学习宏和VBA",
          "steps": [
            "第一步：观看在线教程，学习如何录制宏。",
            "第二步：练习录制一个宏，实现自动填充表格中的数据。",
            "第三步：尝试编写简单的VBA代码，实现自动计算表格中的数据。"
          ],
          "output": "一个包含宏和VBA代码的Excel文件，能够自动填充和计算数据。",
          "tool": "个人电脑，网络教程",
          "example": "Sub AutoFillData() \n Range(\"A2\").Select \n ActiveCell.FormulaR1C1 = \"张三\" \n Range(\"B2\").Select \n ActiveCell.FormulaR1C1 = \"22\" \n End Sub",
          "minutes": 45,
          "why": "通过学习宏和VBA，为提供自动化服务做准备。"
        }
      ]
    },
    {
      "name": "寻找潜在客户",
      "period": "第5-6周",
      "narrative": "虚构测试甲开始寻找潜在客户，通过社交媒体和网络平台发布服务信息。",
      "gate": "能够收集到潜在客户的联系方式。",
      "quests": [
        {
          "title": "发布服务信息",
          "steps": [
            "第一步：在社交媒体上发布服务信息，介绍自己的Excel自动化服务。",
            "第二步：在相关论坛和网站上发布服务信息，吸引潜在客户。",
            "第三步：收集潜在客户的联系方式，准备进行初步沟通。"
          ],
          "output": "收集到的潜在客户联系方式列表。",
          "tool": "社交媒体，网络论坛",
          "example": "客户姓名：李四，联系方式：12345678902",
          "minutes": 45,
          "why": "通过发布服务信息，寻找潜在客户，为后续提供服务做准备。"
        }
      ]
    },
    {
      "name": "提供试单服务",
      "period": "第7-9周",
      "narrative": "虚构测试甲开始提供试单服务，与潜在客户进行初步沟通，了解需求并提供服务。",
      "gate": "能够完成一个试单服务，获得客户的付费。",
      "quests": [
        {
          "title": "提供试单服务",
          "steps": [
            "第一步：与潜在客户进行初步沟通，了解其需求。",
            "第二步：根据客户需求，提供Excel自动化服务，如数据整理、计算等。",
            "第三步：与客户确认服务内容，收取试单费用。"
          ],
          "output": "完成一个试单服务，获得客户的付费。",
          "tool": "个人电脑，网络通讯工具",
          "example": "客户需求：需要整理一份包含姓名、年龄、性别、联系方式的表格，并计算年龄的平均值。",
          "minutes": 45,
          "why": "通过提供试单服务，验证自己的服务能力和市场需求。"
        }
      ]
    }
  ]
}

{
  "title": "财务自动化服务试单",
  "baseline": "基于45岁财务主管的现有技能和资源，利用90天时间，通过现有技能和资源，完成一个Excel表格自动化服务的付费试单。",
  "chapters": [
    {
      "name": "需求调研",
      "period": "第1-2周",
      "narrative": "通过与同行交流，收集潜在客户的需求，确定服务内容。",
      "gate": "收集到至少3个潜在客户的需求，形成需求文档。",
      "quests": [
        {
          "title": "收集需求",
          "steps": [
            "联系3位同行，询问他们对Excel自动化服务的需求。",
            "记录他们的需求，包括具体功能和使用场景。",
            "整理需求文档，列出功能清单和使用场景。"
          ],
          "output": "需求文档，包含3个潜在客户的具体需求和使用场景。",
          "tool": "电子邮件、电话、需求文档模板",
          "example": "需求文档模板：\n1. 需求方：同行A\n   功能：自动计算月度财务报表\n   使用场景：每月初自动生成财务报表\n2. 需求方：同行B\n   功能：自动更新库存数据\n   使用场景：每日更新库存数据，减少人工录入错误",
          "minutes": 30,
          "why": "利用现有资源和技能，通过同行交流收集需求，为后续服务设计提供依据。"
        }
      ]
    },
    {
      "name": "服务设计",
      "period": "第3-4周",
      "narrative": "根据收集到的需求，设计服务方案，包括功能实现和使用说明。",
      "gate": "完成服务方案设计，包括功能实现和使用说明。",
      "quests": [
        {
          "title": "设计服务方案",
          "steps": [
            "根据需求文档，设计服务方案，包括功能实现和使用说明。",
            "编写功能实现步骤，包括Excel公式和操作步骤。",
            "编写使用说明，包括操作步骤和注意事项。"
          ],
          "output": "服务方案设计文档，包含功能实现步骤和使用说明。",
          "tool": "Excel、文档编辑工具",
          "example": "服务方案设计文档：\n1. 功能实现步骤：\n   - 使用VLOOKUP函数自动计算月度财务报表\n   - 使用IF函数自动更新库存数据\n2. 使用说明：\n   - 每月初运行月度财务报表功能\n   - 每日更新库存数据，减少人工录入错误",
          "minutes": 45,
          "why": "根据收集到的需求，设计具体的服务方案，为后续试单提供依据。"
        }
      ]
    },
    {
      "name": "试单准备",
      "period": "第5-6周",
      "narrative": "准备试单所需的Excel表格和数据，确保功能实现。",
      "gate": "完成试单所需的Excel表格和数据准备。",
      "quests": [
        {
          "title": "准备试单数据",
          "steps": [
            "创建试单所需的Excel表格，包括数据列和功能实现。",
            "填充试用数据，确保功能实现。",
            "测试功能实现，确保无误。"
          ],
          "output": "试单所需的Excel表格和数据，包含功能实现和试用数据。",
          "tool": "Excel、试用数据",
          "example": "试单所需的Excel表格：\n1. 数据列：日期、收入、支出、库存\n2. 功能实现：自动计算月度财务报表、自动更新库存数据\n3. 试用数据：\n   - 日期：2023-01-01\n   - 收入：10000\n   - 支出：5000\n   - 库存：1000",
          "minutes": 45,
          "why": "准备试单所需的Excel表格和数据，确保功能实现，为后续试单提供依据。"
        }
      ]
    },
    {
      "name": "试单执行",
      "period": "第7-9周",
      "narrative": "与潜在客户沟通，提供试单服务，收集反馈。",
      "gate": "完成试单服务，收集反馈。",
      "quests": [
        {
          "title": "提供试单服务",
          "steps": [
            "与潜在客户沟通，提供试单服务。",
            "提供试单所需的Excel表格和数据。",
            "收集反馈，记录改进意见。"
          ],
          "output": "试单服务反馈，包含改进意见。",
          "tool": "电子邮件、电话、试单所需的Excel表格和数据",
          "example": "试单服务反馈：\n1. 客户反馈：功能实现良好，但需要增加数据验证功能。\n2. 改进意见：增加数据验证功能，确保数据准确性。",
          "minutes": 45,
          "why": "提供试单服务，收集反馈，为后续改进提供依据。"
        }
      ]
    }
  ]
}

{
  "title": "Excel自动化服务试单推进计划",
  "baseline": "基于现有条件，利用脱敏数据表和同行交流，逐步推进Excel自动化服务试单。",
  "chapters": [
    {
      "name": "制作脱敏样表",
      "period": "第1周",
      "narrative": "由于同行交流未取得进展，需要自己制作脱敏样表，以验证问题和需求。",
      "gate": "完成一个脱敏样表，包含关键列和数据。",
      "quests": [
        {
          "title": "制作脱敏样表",
          "steps": [
            "选择一个典型财务报表，列出关键列名，如日期、金额、科目等。",
            "使用脱敏数据填充关键列，确保数据不涉及敏感信息。",
            "保存样表，确保格式和内容符合财务报表标准。"
          ],
          "output": "一个包含关键列和脱敏数据的财务报表样表。",
          "tool": "Excel",
          "example": "样表包含列名：日期、金额、科目，数据示例：2023-01-01、1000、销售收入。",
          "minutes": 7,
          "why": "利用现有技能和资源，制作脱敏样表，为后续验证需求提供基础。"
        }
      ]
    },
    {
      "name": "验证需求",
      "period": "第2周",
      "narrative": "利用制作的脱敏样表，验证需求和问题。",
      "gate": "确认一个具体问题，如数据处理速度慢、数据准确性问题。",
      "quests": [
        {
          "title": "验证需求",
          "steps": [
            "使用样表进行数据处理，记录处理时间和准确性。",
            "对比处理时间和准确性，确认具体问题。",
            "记录问题描述，如数据处理速度慢、数据准确性问题。"
          ],
          "output": "一份问题描述文档，包含具体问题和验证过程。",
          "tool": "Excel",
          "example": "问题描述：数据处理速度慢，处理1000条数据需要10分钟。",
          "minutes": 7,
          "why": "通过验证需求，确认具体问题，为后续解决方案提供依据。"
        }
      ]
    },
    {
      "name": "设计解决方案",
      "period": "第3周",
      "narrative": "基于验证的问题，设计解决方案。",
      "gate": "完成一个初步的解决方案设计。",
      "quests": [
        {
          "title": "设计解决方案",
          "steps": [
            "根据问题描述，列出可能的解决方案，如使用VBA宏、优化公式等。",
            "选择一个初步的解决方案，如使用VBA宏提高处理速度。",
            "记录解决方案设计，包括步骤和预期效果。"
          ],
          "output": "一份解决方案设计文档，包含初步设计和预期效果。",
          "tool": "Excel",
          "example": "解决方案设计：使用VBA宏提高数据处理速度，预期处理时间减少到1分钟。",
          "minutes": 7,
          "why": "设计解决方案，为后续实施提供具体步骤。"
        }
      ]
    },
    {
      "name": "实施解决方案",
      "period": "第4周",
      "narrative": "基于设计的解决方案，实施并验证效果。",
      "gate": "完成解决方案实施，验证效果。",
      "quests": [
        {
          "title": "实施解决方案",
          "steps": [
            "根据解决方案设计，实施初步的解决方案，如编写VBA宏。",
            "使用样表进行测试，记录处理时间和准确性。",
            "对比实施前后的处理时间和准确性，验证效果。"
          ],
          "output": "一份实施效果报告，包含处理时间和准确性对比。",
          "tool": "Excel",
          "example": "实施效果报告：处理时间从10分钟减少到1分钟，准确性无变化。",
          "minutes": 7,
          "why": "实施解决方案，验证效果，为后续推广提供依据。"
        }
      ]
    }
  ]
}
